// Package planner enumerates placement candidates for a task on a
// machine and ranks them with the cost model.
//
// Generation strategy (documented honestly in docs/ALGORITHM.md):
//
//   - Whole-stage assignments are generated by dynamic programming:
//     stage time depends on the stage's own unit plus the transfer
//     from the previous stage's unit, so a shortest-path DP over
//     (stage, unit) finds the time-optimal whole-stage assignment
//     under the cost model. DP ignores global capacity; feasibility
//     is enforced by evaluating every candidate with package cost.
//   - A capacity-greedy assignment complements the DP when the
//     time-optimal plan overflows a small memory domain.
//   - Parallel splits use shares proportional to MEASURED per-stage
//     throughput (never VRAM ratios), capped by each domain's
//     capacity via water-filling.
//   - Tier-offload variants move expert bytes (or whole stages) to a
//     larger, slower domain — the generalized MoE-offload move.
//   - Speculation variants are generated only for tasks that declare
//     a measured acceptance rate; they must win in the cost model,
//     and ultimately in the tuner, to be chosen.
//
// The planner is a heuristic candidate generator + exact evaluation,
// not a proven optimizer; package sim measures its optimality gap.
package planner

import (
	"fmt"
	"math"
	"sort"

	"yosegi/cost"
	"yosegi/device"
	"yosegi/workload"
)

// ScoredPlan is a plan with its predicted cost.
type ScoredPlan struct {
	Plan   cost.Plan
	Result cost.Result
}

// Outcome is the planner's answer.
type Outcome struct {
	// Feasible plans, best first (at most K).
	Top []ScoredPlan
	// NoFit is set when nothing feasible was found.
	NoFit *NoFitReport
}

// NoFitReport explains, honestly, why a task does not fit and what
// would change that.
type NoFitReport struct {
	Reasons     []string // blocking constraints from the best attempts
	Suggestions []string // reductions / changes that DO fit, when found
}

// Options tunes candidate generation.
type Options struct {
	TopK        int // plans to return (default 5)
	MaxSplit    int // max units in a split subset (default 4)
	WithSpec    bool
	WithOffload bool
}

func (o *Options) defaults() {
	if o.TopK <= 0 {
		o.TopK = 5
	}
	if o.MaxSplit <= 0 {
		o.MaxSplit = 4
	}
}

// Solve plans a task on a machine.
func Solve(m *device.Machine, t workload.Task, opts Options) Outcome {
	opts.defaults()
	cands := generate(m, t, opts)
	return rank(m, t, cands, opts, true)
}

// rank scores candidates; polish=false skips the local-search phase
// (used for the recursive feasibility probes of declared reductions,
// where only "does it fit" matters, not the polished time).
func rank(m *device.Machine, t workload.Task, cands []cost.Plan, opts Options, polish bool) Outcome {
	seen := map[string]bool{}
	var scored []ScoredPlan
	var infeasible []cost.Plan
	for _, p := range cands {
		id := p.ID()
		if seen[id] {
			continue
		}
		seen[id] = true
		r := cost.Evaluate(m, t, p)
		if r.Feasible {
			scored = append(scored, ScoredPlan{Plan: p, Result: r})
		} else {
			infeasible = append(infeasible, p)
		}
	}
	// Polish: hill-climb the best feasible plan, and repair +
	// hill-climb a few infeasible candidates (the time-optimal
	// assignment often only needs one stage moved out of an
	// overflowing memory domain).
	if polish {
		best := -1
		for i := range scored {
			if best < 0 || scored[i].Result.TotalTime < scored[best].Result.TotalTime {
				best = i
			}
		}
		if best >= 0 {
			if p := hillClimb(m, t, scored[best].Plan); !seen[p.ID()] {
				seen[p.ID()] = true
				scored = append(scored, ScoredPlan{Plan: p, Result: cost.Evaluate(m, t, p)})
			}
		}
		repaired := 0
		for _, ip := range infeasible {
			if repaired >= 6 {
				break
			}
			rp, ok := repair(m, t, ip)
			if !ok {
				continue
			}
			repaired++
			rp = hillClimb(m, t, rp)
			if seen[rp.ID()] {
				continue
			}
			seen[rp.ID()] = true
			if rr := cost.Evaluate(m, t, rp); rr.Feasible {
				scored = append(scored, ScoredPlan{Plan: rp, Result: rr})
			}
		}
		// Multi-start: also climb from the best few distinct feasible
		// shapes — different starts fall into different local optima.
		climbed := 0
		for i := range scored {
			if climbed >= 3 {
				break
			}
			climbed++
			if p := hillClimb(m, t, scored[i].Plan); !seen[p.ID()] {
				seen[p.ID()] = true
				if rr := cost.Evaluate(m, t, p); rr.Feasible {
					scored = append(scored, ScoredPlan{Plan: p, Result: rr})
				}
			}
		}
	}
	sort.SliceStable(scored, func(i, j int) bool {
		a, b := scored[i], scored[j]
		if math.Abs(a.Result.TotalTime-b.Result.TotalTime) > 0.01*a.Result.TotalTime {
			return a.Result.TotalTime < b.Result.TotalTime
		}
		return a.Plan.Complexity() < b.Plan.Complexity()
	})
	out := Outcome{}
	if len(scored) > 0 {
		if len(scored) > opts.TopK {
			scored = scored[:opts.TopK]
		}
		out.Top = scored
		return out
	}
	// Nothing fit: explain, and test the declared reductions.
	rep := &NoFitReport{}
	reasonSet := map[string]bool{}
	for _, p := range infeasible {
		for _, reason := range cost.Evaluate(m, t, p).Reasons {
			if !reasonSet[reason] {
				reasonSet[reason] = true
				rep.Reasons = append(rep.Reasons, reason)
			}
		}
	}
	if len(rep.Reasons) == 0 {
		rep.Reasons = append(rep.Reasons, "no candidate plan could be constructed")
	}
	for _, red := range t.Reductions {
		if len(rep.Suggestions) >= 2 {
			break // two tested ways out are enough to act on
		}
		reduced := t.ApplyReduction(red)
		// Feasibility probe only: no local-search polish, so testing
		// the whole ladder stays cheap even for many-stage tasks.
		subOpts := Options{TopK: 1, MaxSplit: opts.MaxSplit, WithSpec: false, WithOffload: opts.WithOffload}
		subOpts.defaults()
		sub := rank(m, reduced, generate(m, reduced, subOpts), subOpts, false)
		if len(sub.Top) > 0 {
			rep.Suggestions = append(rep.Suggestions, fmt.Sprintf(
				"reduction %q fits (predicted %.3f s): %s", red.Name, sub.Top[0].Result.TotalTime, red.Note))
		}
	}
	if len(rep.Suggestions) == 0 {
		rep.Suggestions = append(rep.Suggestions,
			"no declared reduction fits either; a smaller task, a shorter context/window, or more memory capacity is required")
	}
	out.NoFit = rep
	return out
}

// generate builds the candidate set (unevaluated).
func generate(m *device.Machine, t workload.Task, opts Options) []cost.Plan {
	var out []cost.Plan
	units := m.Units
	if len(units) == 0 || len(t.Stages) == 0 {
		return out
	}
	// 1. Single-unit plans.
	for _, u := range units {
		out = append(out, wholePlan(t, func(int) string { return u.ID }))
	}
	// 2. DP assignments: plain, plus penalty iterations that steer
	// the DP away from memory domains its previous solution
	// overflowed (a cheap Lagrangian-style repair for capacity).
	out = append(out, dpVariants(m, t)...)
	// 3. Capacity-greedy assignments (in order, and by stage size).
	out = append(out, greedyAssign(m, t))
	out = append(out, greedyBySize(m, t))
	// 4. Proportional splits over unit subsets.
	maxSplit := opts.MaxSplit
	if maxSplit > len(units) {
		maxSplit = len(units)
	}
	for size := 2; size <= maxSplit; size++ {
		for _, subset := range subsets(units, size) {
			if p, ok := splitPlan(m, t, subset); ok {
				out = append(out, p)
			}
		}
	}
	// 5. Tier-offload variants of the structural candidates so far.
	if opts.WithOffload {
		out = append(out, offloadVariants(m, t, out)...)
	}
	// 6. Speculation variants over the current best shapes.
	if opts.WithSpec && t.Spec != nil {
		out = append(out, specVariants(m, t, out)...)
	}
	return out
}

func wholePlan(t workload.Task, pick func(stage int) string) cost.Plan {
	p := cost.Plan{Placements: make([]cost.Placement, len(t.Stages))}
	for i := range t.Stages {
		p.Placements[i] = cost.Placement{Units: []string{pick(i)}, Shares: []float64{1}}
	}
	return p
}

// stageTimeOn estimates one stage wholly on one unit (peak rates;
// the authoritative thermal/cache accounting happens in cost).
func stageTimeOn(m *device.Machine, st workload.Stage, u device.Unit) float64 {
	mem, _ := m.Memory(u.MemoryID)
	ct := st.Compute / u.ComputeRate
	mt := float64(st.StreamedBytes()) / mem.BandwidthBytesSec
	t := math.Max(ct, mt)
	if st.IOBytes > 0 {
		bw := m.FastestStorageRead()
		if bw <= 0 {
			bw = 5e8
		}
		if io := float64(st.IOBytes) / bw; io > t {
			t = io
		}
	}
	return t
}

// dpOption is one per-stage placement choice inside the DP: a whole
// assignment to one unit, or the split-across-all-units placement.
type dpOption struct {
	pl     cost.Placement
	time   float64 // stage-local time at peak rates (generator metric)
	domain string  // home domain for transfer accounting
}

// stageOptions enumerates a stage's DP options, with optional
// per-unit time penalties (capacity steering).
func stageOptions(m *device.Machine, t workload.Task, i int, penalty map[string]float64) []dpOption {
	st := t.Stages[i]
	var opts []dpOption
	for _, u := range m.Units {
		if !st.Allows(u) {
			continue
		}
		f := penalty[u.ID]
		if f <= 0 {
			f = 1
		}
		opts = append(opts, dpOption{
			pl:     cost.Placement{Units: []string{u.ID}, Shares: []float64{1}},
			time:   stageTimeOn(m, st, u) * f,
			domain: u.MemoryID,
		})
	}
	if st.Splittable {
		if pl, ok := SplitPlacement(m, st, t.TotalFootprint(), m.Units); ok && len(pl.Units) > 1 {
			opts = append(opts, dpOption{
				pl:     pl,
				time:   stageSplitTime(m, st, pl),
				domain: dominantDomain(m, pl),
			})
		}
	}
	return opts
}

// stageSplitTime times one stage under an arbitrary placement with
// the cost model's roofline (generator metric; cost.Evaluate remains
// authoritative for ranking).
func stageSplitTime(m *device.Machine, st workload.Stage, pl cost.Placement) float64 {
	groupBytes := map[string]float64{}
	for j, uid := range pl.Units {
		u, _ := m.Unit(uid)
		dom := pl.Tier
		if dom == "" {
			dom = u.MemoryID
		}
		groupBytes[dom] += shareOf(pl, j) * float64(st.StreamedBytes())
	}
	best := 0.0
	for j, uid := range pl.Units {
		u, _ := m.Unit(uid)
		dom := pl.Tier
		if dom == "" {
			dom = u.MemoryID
		}
		mem, _ := m.Memory(dom)
		ct := shareOf(pl, j) * st.Compute / u.ComputeRate
		mt := groupBytes[dom] / mem.BandwidthBytesSec
		if v := math.Max(ct, mt); v > best {
			best = v
		}
	}
	if len(pl.Units) > 1 && st.SplitSyncCost > 0 {
		best *= 1 + st.SplitSyncCost*float64(len(pl.Units)-1)
	}
	if st.IOBytes > 0 {
		bw := m.FastestStorageRead()
		if bw <= 0 {
			bw = 5e8
		}
		if io := float64(st.IOBytes) / bw; io > best {
			best = io
		}
	}
	return best
}

func shareOf(pl cost.Placement, j int) float64 {
	if j < len(pl.Shares) {
		return pl.Shares[j]
	}
	if len(pl.Units) == 1 {
		return 1
	}
	return 0
}

// dominantDomain is the memory domain of a placement's largest share.
func dominantDomain(m *device.Machine, pl cost.Placement) string {
	best, bestShare := "", -1.0
	for j, uid := range pl.Units {
		if s := shareOf(pl, j); s > bestShare {
			bestShare = s
			u, _ := m.Unit(uid)
			best = u.MemoryID
			if pl.Tier != "" {
				best = pl.Tier
			}
		}
	}
	return best
}

// dpAssign finds the time-optimal assignment by DP over (stage,
// option), charging inter-domain transfers between consecutive
// stages. Capacity is NOT considered here (cost.Evaluate filters);
// penalty steers stage times per unit for the repair iterations.
func dpAssign(m *device.Machine, t workload.Task, penalty map[string]float64) (cost.Plan, bool) {
	n := len(t.Stages)
	if n == 0 || len(m.Units) == 0 {
		return cost.Plan{}, false
	}
	const inf = math.MaxFloat64
	options := make([][]dpOption, n)
	for i := range t.Stages {
		options[i] = stageOptions(m, t, i, penalty)
		if len(options[i]) == 0 {
			return cost.Plan{}, false
		}
	}
	dp := make([][]float64, n)
	back := make([][]int, n)
	for i := range dp {
		dp[i] = make([]float64, len(options[i]))
		back[i] = make([]int, len(options[i]))
		for j := range dp[i] {
			dp[i][j] = inf
		}
	}
	for j, o := range options[0] {
		dp[0][j] = o.time
		back[0][j] = -1
	}
	for i := 1; i < n; i++ {
		for j, o := range options[i] {
			best, arg := inf, -1
			for v, po := range options[i-1] {
				if dp[i-1][v] >= inf {
					continue
				}
				c := dp[i-1][v]
				if po.domain != o.domain && t.Stages[i-1].Activation > 0 {
					bw, lat := m.Transfer(po.domain, o.domain)
					c += float64(t.Stages[i-1].Activation)/bw + lat
				}
				if c < best {
					best, arg = c, v
				}
			}
			if arg >= 0 {
				dp[i][j] = best + o.time
				back[i][j] = arg
			}
		}
	}
	last := -1
	for j := range options[n-1] {
		if dp[n-1][j] < inf && (last < 0 || dp[n-1][j] < dp[n-1][last]) {
			last = j
		}
	}
	if last < 0 {
		return cost.Plan{}, false
	}
	p := cost.Plan{Placements: make([]cost.Placement, n)}
	for i, j := n-1, last; i >= 0; i-- {
		p.Placements[i] = options[i][j].pl
		j = back[i][j]
	}
	return p, true
}

// dpVariants runs the DP, then up to 3 repair iterations: domains
// whose footprint overflows get their units' stage times penalized
// x4, and the DP runs again. Every distinct result is a candidate.
func dpVariants(m *device.Machine, t workload.Task) []cost.Plan {
	var out []cost.Plan
	penalty := map[string]float64{}
	seen := map[string]bool{}
	for iter := 0; iter < 4; iter++ {
		p, ok := dpAssign(m, t, penalty)
		if !ok {
			break
		}
		id := p.ID()
		if seen[id] {
			break
		}
		seen[id] = true
		out = append(out, p)
		// Find overflowing domains under this plan.
		used := map[string]int64{}
		for i, pl := range p.Placements {
			for j, uid := range pl.Units {
				u, _ := m.Unit(uid)
				dom := u.MemoryID
				if pl.Tier != "" {
					dom = pl.Tier
				}
				used[dom] += int64(float64(t.Stages[i].Footprint) * shareOf(pl, j))
			}
		}
		steered := false
		for dom, bytes := range used {
			mem, _ := m.Memory(dom)
			if mem.CapacityBytes > 0 && bytes > mem.CapacityBytes {
				for _, u := range m.Units {
					if u.MemoryID == dom {
						if penalty[u.ID] <= 0 {
							penalty[u.ID] = 1
						}
						penalty[u.ID] *= 4
						steered = true
					}
				}
			}
		}
		if !steered {
			break
		}
	}
	return out
}

// greedyBySize decides placements largest-footprint-first (the
// classic bin-packing order), which escapes some in-order greedy
// dead ends; the resulting plan is still in stage order.
func greedyBySize(m *device.Machine, t workload.Task) cost.Plan {
	order := make([]int, len(t.Stages))
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool {
		return t.Stages[order[a]].Footprint > t.Stages[order[b]].Footprint
	})
	chosen := greedyCore(m, t, order)
	return wholePlan(t, func(i int) string { return chosen[i] })
}

// greedyCore picks a unit per stage in the given decision order.
func greedyCore(m *device.Machine, t workload.Task, order []int) []string {
	remaining := map[string]int64{}
	for _, mem := range m.Memories {
		remaining[mem.ID] = mem.CapacityBytes
	}
	chosen := make([]string, len(t.Stages))
	for _, i := range order {
		chosen[i] = greedyPick(m, t.Stages[i], remaining)
	}
	return chosen
}

func greedyPick(m *device.Machine, st workload.Stage, remaining map[string]int64) string {
	bestID := ""
	bestTime := math.Inf(1)
	for _, u := range m.Units {
		if st.Allows(u) && remaining[u.MemoryID] >= st.Footprint {
			if tt := stageTimeOn(m, st, u); tt < bestTime {
				bestTime, bestID = tt, u.ID
			}
		}
	}
	if bestID == "" {
		for _, u := range m.Units {
			if st.Allows(u) {
				if tt := stageTimeOn(m, st, u); tt < bestTime {
					bestTime, bestID = tt, u.ID
				}
			}
		}
	}
	for _, u := range m.Units {
		if u.ID == bestID {
			remaining[u.MemoryID] -= st.Footprint
		}
	}
	return bestID
}

// greedyAssign walks stages in order, placing each on the fastest
// unit whose home domain still has room for the stage's footprint.
func greedyAssign(m *device.Machine, t workload.Task) cost.Plan {
	remaining := map[string]int64{}
	for _, mem := range m.Memories {
		remaining[mem.ID] = mem.CapacityBytes
	}
	return wholePlan(t, func(i int) string {
		st := t.Stages[i]
		bestID := ""
		bestTime := math.Inf(1)
		for _, u := range m.Units {
			if st.Allows(u) && remaining[u.MemoryID] >= st.Footprint {
				if tt := stageTimeOn(m, st, u); tt < bestTime {
					bestTime, bestID = tt, u.ID
				}
			}
		}
		if bestID == "" {
			// Nothing allowed has room; put it on the fastest allowed
			// unit and let evaluation report the overflow honestly.
			for _, u := range m.Units {
				if st.Allows(u) {
					if tt := stageTimeOn(m, st, u); tt < bestTime {
						bestTime, bestID = tt, u.ID
					}
				}
			}
		}
		for _, u := range m.Units {
			if u.ID == bestID {
				remaining[u.MemoryID] -= st.Footprint
			}
		}
		return bestID
	})
}

// splitPlan builds a plan splitting every splittable stage across the
// subset with shares proportional to measured per-stage throughput,
// capped by domain capacity (water-filling). Non-splittable stages go
// wholly to the subset's fastest unit for that stage.
func splitPlan(m *device.Machine, t workload.Task, subset []device.Unit) (cost.Plan, bool) {
	p := cost.Plan{Placements: make([]cost.Placement, len(t.Stages))}
	totalFoot := t.TotalFootprint()
	for i, st := range t.Stages {
		var allowed []device.Unit
		for _, u := range subset {
			if st.Allows(u) {
				allowed = append(allowed, u)
			}
		}
		if len(allowed) == 0 {
			return cost.Plan{}, false
		}
		if !st.Splittable || len(allowed) == 1 {
			best := allowed[0]
			bestT := math.Inf(1)
			for _, u := range allowed {
				if tt := stageTimeOn(m, st, u); tt < bestT {
					bestT, best = tt, u
				}
			}
			p.Placements[i] = cost.Placement{Units: []string{best.ID}, Shares: []float64{1}}
			continue
		}
		pl, ok := SplitPlacement(m, st, totalFoot, allowed)
		if !ok {
			return cost.Plan{}, false
		}
		p.Placements[i] = pl
	}
	return p, true
}

// SplitPlacement builds the parallel-split placement of one stage
// across a unit subset: shares proportional to measured per-stage
// throughput, capped by each home domain's capacity share of the
// task's total footprint (water-filling). Exported so the simulator's
// brute force searches exactly the same split shapes.
func SplitPlacement(m *device.Machine, st workload.Stage, totalFoot int64, subset []device.Unit) (cost.Placement, bool) {
	var allowed []device.Unit
	for _, u := range subset {
		if st.Allows(u) {
			allowed = append(allowed, u)
		}
	}
	subset = allowed
	if len(subset) == 0 {
		return cost.Placement{}, false
	}
	weights := make([]float64, len(subset))
	caps := make([]float64, len(subset))
	for j, u := range subset {
		tt := stageTimeOn(m, st, u)
		if tt > 0 {
			weights[j] = 1 / tt
		} else {
			weights[j] = 1
		}
		mem, _ := m.Memory(u.MemoryID)
		if totalFoot > 0 && mem.CapacityBytes > 0 {
			caps[j] = float64(mem.CapacityBytes) / float64(totalFoot)
		} else {
			caps[j] = 1
		}
	}
	shares := cappedShares(weights, caps)
	if shares == nil {
		return cost.Placement{}, false
	}
	pl := cost.Placement{}
	for j, u := range subset {
		if shares[j] > 0 {
			pl.Units = append(pl.Units, u.ID)
			pl.Shares = append(pl.Shares, shares[j])
		}
	}
	if len(pl.Units) == 0 {
		return cost.Placement{}, false
	}
	return pl, true
}

// cappedShares converts weights to shares proportional to weight,
// with no share exceeding its cap; capped weight is redistributed to
// the rest (water-filling). Returns nil when the caps sum to < 1.
func cappedShares(weights, caps []float64) []float64 {
	n := len(weights)
	sumCaps := 0.0
	for _, c := range caps {
		sumCaps += c
	}
	if sumCaps < 1 {
		return nil
	}
	shares := make([]float64, n)
	active := make([]bool, n)
	for i := range active {
		active[i] = true
	}
	remaining := 1.0
	for remaining > 1e-9 {
		wsum := 0.0
		for i := range weights {
			if active[i] {
				wsum += weights[i]
			}
		}
		if wsum <= 0 {
			return nil
		}
		progressed := false
		for i := range weights {
			if !active[i] {
				continue
			}
			s := remaining * weights[i] / wsum
			if s >= caps[i]-shares[i] {
				remaining -= caps[i] - shares[i]
				shares[i] = caps[i]
				active[i] = false
				progressed = true
			}
		}
		if !progressed {
			for i := range weights {
				if active[i] {
					shares[i] += remaining * weights[i] / wsum
				}
			}
			remaining = 0
		}
	}
	return shares
}

// offloadVariants derives tier-offload variants: expert bytes of all
// stages moved to the largest other memory domain, and (for plans
// whose stages sit in a small domain) whole stages moved there.
func offloadVariants(m *device.Machine, t workload.Task, base []cost.Plan) []cost.Plan {
	// The offload target: the largest memory domain that is not a
	// GPU-local domain of any single small unit — in practice RAM.
	target := ""
	var bestCap int64
	for _, mem := range m.Memories {
		if mem.CapacityBytes > bestCap {
			bestCap, target = mem.CapacityBytes, mem.ID
		}
	}
	if target == "" {
		return nil
	}
	var out []cost.Plan
	seen := map[string]bool{}
	add := func(p cost.Plan) {
		id := p.ID()
		if !seen[id] {
			seen[id] = true
			out = append(out, p)
		}
	}
	for _, b := range base {
		// Expert-tier offload (MoE move).
		hasExpert := false
		for _, st := range t.Stages {
			if st.ExpertBytes > 0 {
				hasExpert = true
			}
		}
		if hasExpert {
			p := clonePlan(b)
			for i := range p.Placements {
				p.Placements[i].ExpertTier = target
			}
			add(p)
		}
		// Whole-tier offload of every stage.
		p := clonePlan(b)
		for i := range p.Placements {
			p.Placements[i].Tier = target
		}
		add(p)
	}
	return out
}

// specVariants derives speculation variants from the given base plans:
// depths {1,2,3,5,8} up to the task's cap, draft on each unit.
func specVariants(m *device.Machine, t workload.Task, base []cost.Plan) []cost.Plan {
	depths := []int{1, 2, 3, 5, 8}
	var out []cost.Plan
	seen := map[string]bool{}
	// Bound the work: speculate only over the first few distinct base
	// shapes.
	used := 0
	for _, b := range base {
		if used >= 3 {
			break
		}
		used++
		for _, d := range depths {
			if d > t.Spec.MaxDepth {
				continue
			}
			for _, u := range m.Units {
				p := clonePlan(b)
				p.Spec = &cost.SpecChoice{Depth: d, DraftUnit: u.ID}
				id := p.ID()
				if !seen[id] {
					seen[id] = true
					out = append(out, p)
				}
			}
		}
	}
	return out
}

func clonePlan(p cost.Plan) cost.Plan {
	out := cost.Plan{Placements: make([]cost.Placement, len(p.Placements))}
	for i, pl := range p.Placements {
		out.Placements[i] = cost.Placement{
			Units:      append([]string(nil), pl.Units...),
			Shares:     append([]float64(nil), pl.Shares...),
			Tier:       pl.Tier,
			ExpertTier: pl.ExpertTier,
		}
	}
	if p.Spec != nil {
		s := *p.Spec
		out.Spec = &s
	}
	return out
}

// subsets enumerates all subsets of units of the given size.
func subsets(units []device.Unit, size int) [][]device.Unit {
	var out [][]device.Unit
	var rec func(start int, cur []device.Unit)
	rec = func(start int, cur []device.Unit) {
		if len(cur) == size {
			cp := append([]device.Unit(nil), cur...)
			out = append(out, cp)
			return
		}
		for i := start; i < len(units); i++ {
			rec(i+1, append(cur, units[i]))
		}
	}
	rec(0, nil)
	return out
}
